"""Root's exact post-amendment scope/instantiates revalidation; no home/identity."""
import hashlib,json
from pathlib import Path
B=Path(__file__).resolve().parent;F=B.parent;W=F.parents[3]
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
auditpath=B/'premise-dependency-audit.json';audit=json.loads(auditpath.read_text());assert sha(auditpath)=='bccfd07432ba749ae916c824e107e5e11f8ee56619fc8e0a63cbeed421089860'
componentpath=F/'admissions-v2/supported-scope-role-component-v2.json';component=json.loads(componentpath.read_text());target=audit['dependentScopeContributions'][0];assert len(audit['dependentScopeContributions'])==1 and target['role']=='instantiates'
scope=next(d for d in component['destinations'] if d['id']==target['candidateId']);row=next(r for r in component['sourceContributions'] if r['unitId']==target['unitId'] and r['destinationId']==scope['id'] and r['role']=='instantiates');decision=next(d for d in component['decisions'] if d['id']==row['decisionId'])
receipt={'schemaVersion':'q025-post-premise-amendment-revalidation/1','status':'accepted_unchanged_scope_and_typed_contribution','adjudicator':'root','authorization':'Root independently read the full p6 scope, both unit notes and primary e12/e19. The unchanged scope and exact instantiates role remain compatible with the amended canonical induced-mass evidence. Additive K/W separation already does not imply gravitational decoupling in this scope, which excludes generalization to every Kähler geometry.','amendment':audit['amendmentAdmission'],'dependencyAudit':{'path':str(auditpath.relative_to(W)),'sha256':sha(auditpath)},'component':{'path':str(componentpath.relative_to(W)),'sha256':sha(componentpath)},'destinationId':scope['id'],'scopeContentSha256':scope['scopeContentSha256'],'unitId':row['unitId'],'role':row['role'],'sourceContributionDecisionId':row['decisionId'],'contributionContentSha256':decision['contributionContentSha256'],'sourceReadingBasis':row['basis'],'evidenceRefs':row['evidenceRefs'],'originalIncorrectFactorRetained':True,'factorRef':audit['amendedFactorRefs'][0],'fineQuestionIdentity':'unresolved_setting_and_example_not_an_independently_isolated_canonical_question','homesAdmitted':0,'identityMergesAdmitted':0,'publicRelationsAdmitted':0,'scopeDefinitionChanges':0}
p=B/'premise-revalidation.json';p.write_text(json.dumps(receipt,ensure_ascii=False,indent=2)+'\n');overlaypath=B/'intake-overlay.json';overlay=json.loads(overlaypath.read_text());overlay['priorOverlay']={'path':str(overlaypath.relative_to(W)),'sha256':sha(overlaypath)};overlay['schemaVersion']='q025-resolved-annotation-intake-overlay/2';overlay['premiseRevalidations']=[{'path':str(p.relative_to(W)),'sha256':sha(p),'destinationId':scope['id'],'scopeContentSha256':scope['scopeContentSha256'],'unitId':row['unitId'],'role':row['role'],'contributionContentSha256':decision['contributionContentSha256']}]
for factor in overlay['factorQualificationResolutions']:
 if factor['factorRef']==audit['amendedFactorRefs'][0]:factor['dependencyRevalidationStatus']='completed_for_exact_pinned_scope_and_instantiates_contribution_only';factor['futureUnboundInferencesStillRequireRevalidation']=True
out=B/'intake-overlay-v2.json';out.write_text(json.dumps(overlay,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'revalidationSha256':sha(p),'overlayV2Sha256':sha(out),'scopeUnchanged':scope['id'],'role':'instantiates','homes':0,'identityStillUnresolved':True}))
